PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('owner','admin','reviewer','member','reader')), must_change INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, membership TEXT NOT NULL DEFAULT 'pending' CHECK(membership IN ('pending','official')), membership_reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS documents(slug TEXT PRIMARY KEY, title TEXT NOT NULL, intro TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'proposal', html TEXT NOT NULL, updated TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS drive_items(id INTEGER PRIMARY KEY, path TEXT UNIQUE NOT NULL, parent_path TEXT, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('folder','file','native')), media_type TEXT NOT NULL DEFAULT '', size INTEGER NOT NULL DEFAULT 0, local_rel TEXT NOT NULL DEFAULT '', remote_path TEXT NOT NULL DEFAULT '', source_revision TEXT NOT NULL DEFAULT '', mtime TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, indexed TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY, document TEXT NOT NULL REFERENCES documents(slug), version INTEGER NOT NULL, html TEXT NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', author INTEGER REFERENCES users(id), source_thread INTEGER, created TEXT NOT NULL, UNIQUE(document,version));
CREATE TABLE IF NOT EXISTS threads(id INTEGER PRIMARY KEY, document TEXT NOT NULL REFERENCES documents(slug), version INTEGER NOT NULL, section TEXT NOT NULL, section_title TEXT NOT NULL, section_snapshot TEXT NOT NULL, quote TEXT NOT NULL DEFAULT '', prefix TEXT NOT NULL DEFAULT '', suffix TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, topic TEXT NOT NULL, author INTEGER NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closing','archived')), summary TEXT NOT NULL DEFAULT '', outcome TEXT NOT NULL DEFAULT '', revision_id INTEGER REFERENCES revisions(id), created TEXT NOT NULL, updated TEXT NOT NULL, target_type TEXT NOT NULL DEFAULT 'document', drive_item_id INTEGER REFERENCES drive_items(id));
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL REFERENCES threads(id), author INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL REFERENCES threads(id), payload TEXT NOT NULL, source TEXT NOT NULL, comment_count INTEGER NOT NULL, document_version INTEGER NOT NULL, approved INTEGER NOT NULL DEFAULT 0, author INTEGER NOT NULL REFERENCES users(id), created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY, thread_id INTEGER REFERENCES threads(id), actor INTEGER REFERENCES users(id), kind TEXT NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_jobs(id INTEGER PRIMARY KEY, thread_id INTEGER NOT NULL REFERENCES threads(id), actor INTEGER NOT NULL REFERENCES users(id), state TEXT NOT NULL DEFAULT 'queued', error TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, started TEXT, finished TEXT);
CREATE TABLE IF NOT EXISTS development_items(key TEXT PRIMARY KEY, title TEXT NOT NULL, question TEXT NOT NULL, classification TEXT NOT NULL, origin TEXT NOT NULL DEFAULT '', sort_order INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','answered','needs_clarification','in_progress','implemented','deferred','closed')), created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_responses(id INTEGER PRIMARY KEY, item_key TEXT NOT NULL REFERENCES development_items(key), author INTEGER NOT NULL REFERENCES users(id), body TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS development_events(id INTEGER PRIMARY KEY, item_key TEXT NOT NULL REFERENCES development_items(key), actor INTEGER REFERENCES users(id), kind TEXT NOT NULL, detail TEXT NOT NULL, created TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_comments_thread ON comments(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_events_thread ON events(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_reviews_thread ON reviews(thread_id,id);
CREATE INDEX IF NOT EXISTS idx_jobs_state ON ai_jobs(state,id);
CREATE INDEX IF NOT EXISTS idx_drive_parent ON drive_items(parent_path,active,name);
CREATE INDEX IF NOT EXISTS idx_development_responses_item ON development_responses(item_key,id);
CREATE INDEX IF NOT EXISTS idx_development_events_item ON development_events(item_key,id);
